const root=document.getElementById('terms'),toc=document.getElementById('toc'),search=document.getElementById('search'),counter=document.getElementById('counter'),empty=document.getElementById('empty');
document.getElementById('year').textContent=new Date().getFullYear();
const names=[...new Set(clauses.map(x=>x.section))];
function render(q=''){
 const query=q.trim().toLocaleLowerCase('es');
 const found=clauses.map((x,i)=>({...x,n:i+1})).filter(x=>!query||(x.section+' '+x.text).toLocaleLowerCase('es').includes(query));
 root.replaceChildren();const groups=new Map();
 for(const x of found){if(!groups.has(x.section))groups.set(x.section,[]);groups.get(x.section).push(x);}
 for(const [name,items] of groups){
  const article=document.createElement('article');article.className='section';
  const h=document.createElement('h2');h.textContent=name;article.appendChild(h);
  for(const x of items){const row=document.createElement('div');row.className='clause';const n=document.createElement('span');n.className='num';n.textContent=String(x.n).padStart(4,'0');const p=document.createElement('p');p.textContent=x.text;row.append(n,p);article.appendChild(row);}
  root.appendChild(article);
 }
 counter.textContent=`Mostrando ${found.length.toLocaleString('es')} de 1.000 reglas`;empty.hidden=found.length!==0;
}
for(const name of names){const a=document.createElement('a');a.href='#';a.textContent=name.replace(/^\\d+\\.\\s*/,'');a.addEventListener('click',e=>{e.preventDefault();[...root.querySelectorAll('.section')].find(s=>s.querySelector('h2').textContent===name)?.scrollIntoView({behavior:'smooth'});});toc.appendChild(a);}
search.addEventListener('input',e=>render(e.target.value));render();
